/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import {
  AbsoluteFill,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  interpolate,
  Sequence,
  type SequenceControls,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useContext,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (isDev()) {
      console.warn(`parseColor could not parse "${s}"; using black.`);
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * A token at partial opacity — for scrims, veils and inner washes.
 *
 * A scrim written as a literal `rgba(0,0,0,0.4)` is lit for a light surface and
 * does nothing on a dark one; `withAlpha(t.foreground, 0.4)` follows the theme
 * and a user's override. Resolves through `parseColor`, so it inherits the same
 * `var()` guard — an unresolvable token degrades to black rather than an
 * invalid colour string mid-render.
 */
function withAlpha(color: string, alpha: number): string {
  const { r, g, b } = parseColor(color);
  return formatRgb({ mode: "rgb", r, g, b, alpha });
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

export type TerminalLineType = "command" | "log" | "success" | "error";

/** Package-manager command panel — the flythrough's second station. */
export interface CommandSpec {
  /** Tab labels. The first is the active tab. */
  managers?: string[];
  /** The command typed into the active tab, e.g. "npm install One Tool". */
  text: string;
}

export interface TerminalLine {
  text: string;
  type: TerminalLineType;
  /** Frame gap before this line starts typing. Defaults to 8. */
  delay?: number;
  /**
   * Extra freeze-frame pause AFTER this line finishes typing, in frames.
   * Use this to build tension before the next batch of logs. If omitted,
   * lines whose text ends in "..." auto-freeze for 18 frames.
   */
  pause?: number;
}

export interface TerminalZoom {
  /** Turn the extra landing zoom on. */
  enabled: boolean;
  /** Camera zoom the final punch-in lands at. Defaults to 2.4. */
  scale?: number;
  /** Kept for API compatibility; the flythrough camera always leads the eye. */
  followCursor?: boolean;
}

export interface TerminalSimulatorProps {
  lines?: TerminalLine[];
  /**
   * Headline at the first camera station. Wrap words in `*asterisks*` to tint
   * them with the accent gradient. `null`/"" skips the station — the camera
   * starts on the command panel instead.
   */
  intro?: string | null;
  /**
   * Command panel at the second camera station. `null` skips the station.
   */
  command?: CommandSpec | null;
  /** Command-panel surface color. */
  /** Overrides the design system's `card`. */
  background?: string;
  /** Hairline border color for the command-panel ring and divider. */
  /** Overrides the design system's `border`. */
  borderColor?: string;
  /** Design-system token overrides. */
  theme?: Partial<KitTheme>;
  /** Defaults to `"dark"` — a terminal is lit for dark. */
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
  fontSize?: number;
  /**
   * Reveal speed. The reveal is CHUNKED — every `1 / charsPerFrame` frames
   * bumps the cursor by `chunkSize` characters, so output appears in bursts
   * instead of dripping char-by-char.
   */
  charsPerFrame?: number;
  /** Characters revealed per step. */
  chunkSize?: number;
  /**
   * Landing zoom of the final punch onto the terminal. Pass `true` for the
   * 2.4x default or an object for a custom scale. Off = 1.5x.
   */
  zoom?: boolean | TerminalZoom;
  speed?: number;
  className?: string;
}

// ─── Stage & camera constants ────────────────────────────────────────────────
// The scene is ONE world the camera flies over. Nothing enters from a screen
// edge — the camera pans/zooms between three fixed stations on a single black
// canvas, exactly like a camera-type-flythrough.

// The stage, the panel and the tab row are app chrome and come from the design
// system. The syntax palette below is the terminal's own colour scheme — the
// look, not chrome — and stays literal, exposed through props.

/** Station anchors in world px (world is sized for a 1280x720 viewport). */
const INTRO_POS = { x: 640, y: 360 };
const CMD_POS = { x: 2140, y: 520 };
const TERM_POS = { x: 2140, y: 1660 };

/** Camera timeline (frames at speed 1). */
const DRIFT_START = 22; // intro starts creeping left
const WHIP_START = 40; // sudden acceleration toward the command panel
const CMD_ARRIVE = 70; // camera lands on the command panel
const CMD_TYPE_START = 74; // "npm install One Tool" starts typing
const PUSH_END = 112; // slow push-in while typing (leaves the ghost trail)
const PULL_END = 138; // zoom-out + descend toward the terminal
const PUNCH_END = 158; // sudden punch-in lands on the terminal
const TERM_TYPE_START = 146; // terminal lines start typing as we land

/** Command-panel geometry in world px. */
const CMD_W = 760;
const CMD_H = 170;

/** Terminal station geometry in world px (sized against the reference). */
const TERM_BAR_OFFSET = 137; // bar sits this far left of the focus point
const TERM_TEXT_OFFSET = 90; // text column left edge relative to focus
const TERM_BLOCK_TOP = 215; // first line sits this far above the focus point
const TERM_LINE_H = 83;
const TERM_FONT = 44;

/** Lead-in used for the terminal lines' start schedule. */
const LEAD_IN_FRAMES = 10;

// ─── Palette (matched against the reference stills) ─────────────────────────

/** Accent gradient for `*emphasized*` intro words. */
const ACCENT_GRADIENT = "linear-gradient(90deg, #7C96FF 0%, #A78BFA 100%)";

/** Command-row syntax palette: dim manager/subcommand, highlighted args. */
const CMD_MANAGER_COLOR = "#A0673F";
const CMD_SUBCOMMAND_COLOR = "#64789B";
const CMD_ARG_COLOR = "#D7E4F8";

/** Focus-terminal palette. */
const TERM_ACCENT = "#2EA043";
const TERM_CURSOR = "#1D5B36";
const TERM_COLORS: Record<TerminalLineType, string> = {
  command: "#F2F5F3",
  log: "#6E7873",
  success: "#1F8039",
  error: "#F04438",
};

/**
 * On a light page the two colours drawn for a dark one — near-white args and
 * commands — would vanish, so they take ink instead; the rest read on either.
 */
const LIGHT_ARG_COLOR = "#1B2533";
const LIGHT_TERM_COLORS: Record<TerminalLineType, string> = {
  ...TERM_COLORS,
  command: "#141414",
};

const SANS_FAMILY =
  '-apple-system, BlinkMacSystemFont, "Segoe UI", Inter, sans-serif';
const MONO_FAMILY = "ui-monospace, SFMono-Regular, Menlo, monospace";

const DEFAULT_COMMAND: CommandSpec = {
  managers: ["npm", "pnpm", "yarn", "bun"],
  text: "npm install One Tool",
};

const DEFAULT_LINES: TerminalLine[] = [
  { text: "{labels: ['bug']})", type: "log", delay: 0 },
  { text: "→   label added", type: "success", delay: 6 },
  { text: "$", type: "log", delay: 10 },
  { text: "One task", type: "command", delay: 4 },
];

// ─── Pure helpers ────────────────────────────────────────────────────────────

/** Auto freeze-frame heuristic: any line ending in "..." holds the camera. */
function autoPause(line: TerminalLine): number {
  if (line.pause !== undefined) return line.pause;
  // `replace`, not `trimEnd` (ES2019): stock Remotion types ES2015.
  if (line.text.replace(/\s+$/, "").endsWith("...")) return 18;
  return 0;
}

/** Frames the chunked reveal needs to type `textLength` characters. */
function typingDuration(
  textLength: number,
  charsPerFrame: number,
  chunkSize: number,
): number {
  return Math.ceil(textLength / (chunkSize * charsPerFrame));
}

/**
 * Cumulative start frame for each line, including per-line delays and the
 * auto/explicit freeze pauses AFTER a line finishes typing.
 */
function computeLineStarts(
  lines: TerminalLine[],
  charsPerFrame: number,
  chunkSize: number,
  leadIn: number = LEAD_IN_FRAMES,
): number[] {
  const starts: number[] = [];
  let acc = leadIn;
  for (const line of lines) {
    acc += line.delay ?? 8;
    starts.push(acc);
    acc +=
      typingDuration(line.text.length, charsPerFrame, chunkSize) +
      autoPause(line);
  }
  return starts;
}

/**
 * Chunked reveal: Math.floor of an interpolated count, snapped up to the
 * nearest multiple of `chunkSize`. This is what gives the bursty terminal
 * feel — text doesn't drip, it lurches.
 */
function chunkedReveal(
  localFrame: number,
  totalChars: number,
  charsPerFrame: number,
  chunkSize: number,
): number {
  if (totalChars <= 0) return 0;
  const linear = Math.floor(
    interpolate(localFrame, [0, totalChars / charsPerFrame], [0, totalChars], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
  );
  return Math.min(totalChars, Math.ceil(linear / chunkSize) * chunkSize);
}

/** Normalize the `zoom` prop into a fully-resolved camera config. */
function resolveZoom(
  zoom: boolean | TerminalZoom | undefined,
): Required<TerminalZoom> {
  if (zoom === undefined || zoom === false) {
    return { enabled: false, scale: 1, followCursor: true };
  }
  if (zoom === true) {
    return { enabled: true, scale: 2.4, followCursor: true };
  }
  return {
    enabled: zoom.enabled,
    scale: zoom.scale ?? 2.4,
    followCursor: zoom.followCursor ?? true,
  };
}

/** Split `*emphasis*` runs out of the intro string, preserving spaces. */
function parseIntro(text: string): Array<{ text: string; accent: boolean }> {
  const out: Array<{ text: string; accent: boolean }> = [];
  const re = /\*([^*]+)\*/g;
  let last = 0;
  let m: RegExpExecArray | null = re.exec(text);
  while (m !== null) {
    if (m.index > last)
      out.push({ text: text.slice(last, m.index), accent: false });
    out.push({ text: m[1], accent: true });
    last = m.index + m[0].length;
    m = re.exec(text);
  }
  if (last < text.length) out.push({ text: text.slice(last), accent: false });
  return out;
}

/** Colour a shell command: word 0 = manager, word 1 = subcommand, rest = args. */
function commandSpans(
  text: string,
  argColor: string = CMD_ARG_COLOR,
): Array<{ text: string; color: string }> {
  const out: Array<{ text: string; color: string }> = [];
  let wordIndex = -1;
  for (const part of text.split(/(\s+)/)) {
    if (part.length === 0) continue;
    if (/^\s+$/.test(part)) {
      out.push({ text: part, color: argColor });
      continue;
    }
    wordIndex++;
    const color =
      wordIndex === 0
        ? CMD_MANAGER_COLOR
        : wordIndex === 1
          ? CMD_SUBCOMMAND_COLOR
          : argColor;
    out.push({ text: part, color });
  }
  return out;
}

// ─── Camera ──────────────────────────────────────────────────────────────────

export interface CameraStop {
  /** Frame this stop is reached. */
  frame: number;
  /** World focus point (px) the camera centers on. */
  x: number;
  y: number;
  /** Zoom at this stop. */
  z: number;
  /** Easing applied while travelling INTO this stop from the previous one. */
  easing?: (t: number) => number;
}

export interface CameraState {
  x: number;
  y: number;
  z: number;
}

/**
 * Piecewise camera resolver. Between consecutive stops the camera lerps
 * x/y/z with the segment's own easing — so a lazy drift can hand off to a
 * sudden ease-in whip, which is the whole feel of the flythrough. Clamps to
 * the first/last stop outside the timeline.
 */
function cameraAt(frame: number, stops: CameraStop[]): CameraState {
  const first = stops[0];
  const last = stops[stops.length - 1];
  if (frame <= first.frame) return { x: first.x, y: first.y, z: first.z };
  if (frame >= last.frame) return { x: last.x, y: last.y, z: last.z };
  for (let i = 0; i < stops.length - 1; i++) {
    const a = stops[i];
    const b = stops[i + 1];
    if (frame >= a.frame && frame < b.frame) {
      const t = (frame - a.frame) / (b.frame - a.frame);
      const e = b.easing ? b.easing(t) : t;
      return {
        x: a.x + (b.x - a.x) * e,
        y: a.y + (b.y - a.y) * e,
        z: a.z + (b.z - a.z) * e,
      };
    }
  }
  return { x: last.x, y: last.y, z: last.z };
}

/**
 * The flythrough's shot list: hold on the intro → creep left → sudden
 * ease-in whip to the command panel → slow push while it types (this is
 * what draws the ghost trail) → zoom-out descending → sudden punch-in
 * landing on the terminal. When a station is skipped its segment collapses.
 */
function buildCameraStops(
  hasIntro: boolean,
  hasCommand: boolean,
  landingZoom: number,
): CameraStop[] {
  const whip = Easing.bezier(0.7, 0, 0.25, 1);
  const punch = Easing.bezier(0.75, 0, 0.3, 1);
  const glide = Easing.bezier(0.35, 0, 0.55, 1);

  const stops: CameraStop[] = [];
  if (hasIntro) {
    stops.push(
      { frame: 0, x: INTRO_POS.x, y: INTRO_POS.y, z: 1 },
      { frame: DRIFT_START, x: INTRO_POS.x, y: INTRO_POS.y, z: 1 },
      // The slight leftward text drift = camera creeping right, accelerating.
      {
        frame: WHIP_START,
        x: INTRO_POS.x + 52,
        y: INTRO_POS.y,
        z: 1.02,
        easing: Easing.in(Easing.quad),
      },
    );
  }
  if (hasCommand) {
    stops.push(
      {
        frame: hasIntro ? CMD_ARRIVE : 0,
        x: CMD_POS.x,
        y: CMD_POS.y,
        z: 1.55,
        easing: whip,
      },
      // Slow push-in while the command types — leaves the trailing copies.
      {
        frame: PUSH_END,
        x: CMD_POS.x,
        y: CMD_POS.y + 28,
        z: 1.9,
        easing: Easing.inOut(Easing.quad),
      },
      // Zoom out and start descending toward the terminal.
      {
        frame: PULL_END,
        x: CMD_POS.x,
        y: CMD_POS.y + 630,
        z: 0.95,
        easing: glide,
      },
    );
  }
  stops.push({
    frame: hasCommand ? PUNCH_END : hasIntro ? CMD_ARRIVE : 0,
    x: TERM_POS.x,
    y: TERM_POS.y,
    z: landingZoom,
    easing: punch,
  });
  return stops;
}

/** Screen-space speed of the focus point — drives the motion-blur trail. */
function cameraSpeed(frame: number, stops: CameraStop[]): number {
  const a = cameraAt(frame - 1, stops);
  const b = cameraAt(frame, stops);
  const pan = Math.hypot(b.x - a.x, b.y - a.y) * b.z;
  const zoomEdge = Math.abs(b.z - a.z) * 360;
  return pan + zoomEdge;
}

// ─── Component ───────────────────────────────────────────────────────────────

/** Ghost samples for the motion-blur trail: frames back, opacity, blur px. */
const GHOSTS = [
  { back: 2, alpha: 0.3, blur: 3 },
  { back: 4, alpha: 0.18, blur: 6 },
  { back: 6, alpha: 0.1, blur: 10 },
];

function TerminalSimulatorScene({
  lines = DEFAULT_LINES,
  intro = "*work* one step at a *time.*",
  command = DEFAULT_COMMAND,
  background,
  borderColor,
  theme,
  mode,
  fontFamily,
  fontSize = 18,
  charsPerFrame = 2,
  chunkSize = 3,
  zoom = false,
  speed = 1,
  className,
}: TerminalSimulatorProps) {
  const frame = useCurrentFrame() * speed;
  const { fps, width, height } = useVideoConfig();
  const { isRendering } = getRemotionEnvironment();
  const t = useKitTheme(theme, mode ?? "dark");
  const light = (mode ?? "dark") === "light";
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? SANS_FAMILY;
  const panel = background ?? t.card;
  const hairline = borderColor ?? t.border;
  // One constant stage across the whole flythrough — the page, a shade under
  // the panel that floats on it.
  // A transparent page asks for no page, so the stage under the panel goes too.
  const stage =
    parseColor(t.background).alpha === 0
      ? "transparent"
      : mixOklch(t.background, "#000", 0.35);

  const hasIntro = intro != null && intro.trim().length > 0;
  const hasCommand = command != null && command.text.trim().length > 0;
  const camera = resolveZoom(zoom);
  const landingZoom = camera.enabled ? camera.scale : 1.5;

  const stops = buildCameraStops(hasIntro, hasCommand, landingZoom);
  const cam = cameraAt(frame, stops);
  const speedPx = cameraSpeed(frame, stops);
  // Trail strength ramps in from barely-moving; saturates on the whip.
  const trail = Math.min(1, Math.max(0, (speedPx - 2) / 30));

  const worldTransform = (c: CameraState) =>
    `translate(${width / 2 - c.x * c.z}px, ${height / 2 - c.y * c.z}px) scale(${c.z})`;

  // The world is drawn once per ghost and once under the camera; only the
  // camera's copy hands its lines to Studio, so each line has one outline.
  const world = (primary: boolean) => (
    <WorldContent
      face={face}
      frame={frame}
      fps={fps}
      intro={hasIntro ? intro : null}
      command={hasCommand ? command : null}
      lines={lines}
      background={panel}
      borderColor={hairline}
      ink={t.foreground}
      inkMuted={t.mutedForeground}
      light={light}
      fontSize={fontSize}
      charsPerFrame={charsPerFrame}
      chunkSize={chunkSize}
      hasIntro={hasIntro}
      primary={primary}
    />
  );

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        background: stage,
        textRendering: "geometricPrecision",
      }}
    >
      {/* Motion-blur trail: the same world drawn at recent camera positions.
          Only alive while the camera actually moves — it IS the drop of the
          fast moves, no element ever slides in from a screen edge. */}
      {trail > 0.01 &&
        GHOSTS.map((g) => (
          <div
            key={g.back}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              transformOrigin: "0 0",
              transform: worldTransform(cameraAt(frame - g.back, stops)),
              opacity: g.alpha * trail,
              filter: `blur(${g.blur * trail}px)`,
              pointerEvents: "none",
            }}
          >
            {world(false)}
          </div>
        ))}

      {/* The camera */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          transformOrigin: "0 0",
          transform: worldTransform(cam),
          ...(isRendering ? {} : { willChange: "transform" }),
        }}
      >
        {world(true)}
      </div>
    </div>
  );
}

// ─── World (all three stations on one canvas) ────────────────────────────────

