/** Station 1 — the headline, words fading in staggered. */
function IntroStation({
  frame,
  text,
  fontScale,
  ink,
  face,
}: {
  frame: number;
  text: string;
  fontScale: number;
  ink: string;
  face: string;
}) {
  const tokens = parseIntro(text);
  return (
    <div
      style={{
        position: "absolute",
        left: INTRO_POS.x,
        top: INTRO_POS.y,
        transform: "translate(-50%, -50%)",
        whiteSpace: "pre",
        fontFamily: face,
        fontSize: Math.round(58 * fontScale),
        fontWeight: 600,
        letterSpacing: "-0.01em",
      }}
    >
      {tokens.map((tok, i) => {
        const t = interpolate(frame, [2 + i * 4, 14 + i * 4], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.cubic),
        });
        const style = tok.accent
          ? {
              backgroundImage: ACCENT_GRADIENT,
              WebkitBackgroundClip: "text" as const,
              backgroundClip: "text" as const,
              color: "transparent",
            }
          : { color: ink };
        return (
          <span
            // biome-ignore lint/suspicious/noArrayIndexKey: positional tokens
            key={i}
            style={{ ...style, opacity: t, filter: `blur(${(1 - t) * 3}px)` }}
          >
            {tok.text}
          </span>
        );
      })}
    </div>
  );
}

/** Station 2 — the package-manager panel with the highlighted install command. */
function CommandStation({
  frame,
  command,
  background,
  borderColor,
  ink,
  inkMuted,
  light,
  fontScale,
  charsPerFrame,
  chunkSize,
  fps,
  typeStart,
}: {
  frame: number;
  command: CommandSpec;
  background: string;
  borderColor: string;
  ink: string;
  inkMuted: string;
  light: boolean;
  fontScale: number;
  charsPerFrame: number;
  chunkSize: number;
  fps: number;
  typeStart: number;
}) {
  const argColor = light ? LIGHT_ARG_COLOR : CMD_ARG_COLOR;
  const managers = command.managers?.length ? command.managers : ["npm"];
  const revealed = chunkedReveal(
    Math.max(0, frame - typeStart),
    command.text.length,
    charsPerFrame,
    chunkSize,
  );
  const typingDone = revealed >= command.text.length;
  const blink = Math.floor((frame / fps) * 2) % 2 === 0;
  const spans = commandSpans(command.text, argColor);

  const tabFont = Math.round(20 * fontScale);
  const rowFont = Math.round(33 * fontScale);

  return (
    <div
      style={{
        position: "absolute",
        left: CMD_POS.x - CMD_W / 2,
        top: CMD_POS.y - CMD_H / 2,
        width: CMD_W,
        height: CMD_H,
        background,
        borderRadius: 14,
        overflow: "hidden",
        boxShadow: `0 0 0 1px ${borderColor}, 0 30px 60px ${withAlpha(
          mixOklch(background, "#000", 0.8),
          0.55,
        )}`,
        fontFamily: MONO_FAMILY,
      }}
    >
      {/* Tab row */}
      <div
        style={{
          height: 54,
          display: "flex",
          alignItems: "center",
          gap: 6,
          padding: "0 16px",
          borderBottom: `1px solid ${borderColor}`,
        }}
      >
        {managers.map((m, i) => (
          <div
            key={m}
            style={{
              fontSize: tabFont,
              fontWeight: i === 0 ? 600 : 500,
              padding: "7px 14px",
              borderRadius: 8,
              color: i === 0 ? ink : inkMuted,
              background: i === 0 ? withAlpha(ink, 0.1) : "transparent",
            }}
          >
            {m}
          </div>
        ))}
      </div>

      {/* Command row — manager and subcommand dim, the args highlighted */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          height: CMD_H - 54,
          padding: "0 24px",
          fontSize: rowFont,
          letterSpacing: "0.01em",
          whiteSpace: "pre",
        }}
      >
        {(() => {
          let acc = 0;
          return spans.map((p, i) => {
            const start = acc;
            acc += p.text.length;
            const vis = Math.max(0, Math.min(p.text.length, revealed - start));
            return (
              <span
                // biome-ignore lint/suspicious/noArrayIndexKey: positional spans
                key={i}
                style={{ color: p.color }}
              >
                {p.text.slice(0, vis)}
              </span>
            );
          });
        })()}
        {!typingDone && frame >= typeStart && blink && (
          <span
            style={{
              display: "inline-block",
              width: rowFont * 0.55,
              height: rowFont,
              background: argColor,
              marginLeft: 2,
            }}
          />
        )}
      </div>
    </div>
  );
}

/** Station 3 — the green focus terminal. */
function TerminalStation({
  frame,
  light,
  lines,
  fontScale,
  charsPerFrame,
  chunkSize,
  fps,
  typeStart,
  primary,
}: {
  frame: number;
  light: boolean;
  lines: TerminalLine[];
  fontScale: number;
  charsPerFrame: number;
  chunkSize: number;
  fps: number;
  typeStart: number;
  primary: boolean;
}) {
  const starts = computeLineStarts(lines, charsPerFrame, chunkSize, typeStart);
  const font = Math.round(TERM_FONT * fontScale);
  const blink = Math.floor((frame / fps) * 2) % 2 === 0;

  return (
    <>
      {/* Accent bar */}
      <div
        style={{
          position: "absolute",
          left: TERM_POS.x - TERM_BAR_OFFSET,
          top: TERM_POS.y - 520,
          width: 5,
          height: 1040,
          background: TERM_ACCENT,
          boxShadow: `0 0 22px ${withAlpha(TERM_ACCENT, 0.75)}`,
        }}
      />
      {/* Output column */}
      <div
        style={{
          position: "absolute",
          left: TERM_POS.x - TERM_TEXT_OFFSET,
          top: TERM_POS.y - TERM_BLOCK_TOP,
          fontFamily: MONO_FAMILY,
        }}
      >
        {lines.map((line, index) => {
          const revealed = chunkedReveal(
            Math.max(0, frame - starts[index]),
            line.text.length,
            charsPerFrame,
            chunkSize,
          );
          const typingDone = revealed >= line.text.length;
          const isLast = index === lines.length - 1;
          const showCursor =
            line.type === "command" &&
            frame >= starts[index] &&
            (!typingDone || (isLast && blink));
          return (
            // The line Studio selects is its row: nothing moves a line on its
            // own, the camera carries the whole column.
            <Item
              // biome-ignore lint/suspicious/noArrayIndexKey: lines are positional and never reorder
              key={index}
              index={index}
              primary={primary}
            >
              <div
                style={{
                  height: TERM_LINE_H,
                  display: "flex",
                  alignItems: "center",
                  color: (light ? LIGHT_TERM_COLORS : TERM_COLORS)[line.type],
                  fontSize: font,
                  whiteSpace: "pre",
                }}
              >
                <span>{line.text.substring(0, revealed)}</span>
                {showCursor && (
                  <span
                    style={{
                      display: "inline-block",
                      width: font * 0.6,
                      height: font * 0.95,
                      background: TERM_CURSOR,
                      marginLeft: 6,
                    }}
                  />
                )}
              </div>
            </Item>
          );
        })}
      </div>
    </>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one line at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function TerminalSimulatorPainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}
type TerminalSimulatorLineValues = {
  readonly text?: string;
  readonly type?: string;
};

type TerminalSimulatorLineProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  TerminalSimulatorLineValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this line as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: TerminalSimulatorLineState) => void;
  };

/** What Studio is doing to one line right now, which the stage applies to its node. */
type TerminalSimulatorLineState = {
  values: TerminalSimulatorLineValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const TerminalSimulatorLineSchema = {
  ...Interactive.baseSchema,
  text: { type: "text-content", default: "", description: "Text" },
  type: {
    type: "enum",
    default: "command",
    description: "Kind",
    variants: { command: {}, log: {}, success: {}, error: {} },
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One line: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the line is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const TerminalSimulatorLineInner = forwardRef<
  Element,
  TerminalSimulatorLineProps & {
    readonly controls: SequenceControls | undefined;
  }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      text,
      type,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it, or when its parts move separately; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { text, type },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? TerminalSimulatorPainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Line"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

const TerminalSimulatorLine = Interactive.withSchema({
  Component: TerminalSimulatorLineInner,
  componentName: "<TerminalSimulatorLine>",
  schema: TerminalSimulatorLineSchema,
  supportsEffects: false,
});

