  speed: {
    type: "number",
    default: 1,
    min: 1,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/** The scene's props, from its lines' values in order. */
const TerminalSimulatorFromItems = (
  o: readonly TerminalSimulatorLineValues[],
) => ({
  lines: o.map((x, i) => {
    const type = (x.type ?? "command") as
      | "command"
      | "log"
      | "success"
      | "error";
    return {
      text: x.text ?? "",
      type,
      delay: i === 0 ? 0 : { command: 4, success: 6, error: 6, log: 10 }[type],
    };
  }),
});

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function TerminalSimulatorFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

/** The host, told the frame inside the Element — the one its layers' timing is in. */
function TerminalSimulatorHosted({
  host,
  children,
}: {
  host: (frame: number) => ItemHost;
  children: ReactNode;
}) {
  return (
    <ItemHostProvider value={host(useCurrentFrame())}>
      {children}
    </ItemHostProvider>
  );
}

/**
 * The scene, with its lines as children. It reads their values to lay
 * the scene out, and hands each one back the node the scene draws it as.
 */
const TerminalSimulatorStageInner = forwardRef<
  HTMLDivElement,
  TerminalSimulatorStageProps & {
    readonly controls: SequenceControls | undefined;
  }
>(
  (
    {
      controls,
      name,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      children,
      ...props
    },
    ref,
  ) => {
    const outlineRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
    // One empty box per line on the stage: the outline it falls back to,
    // which it moves over the part of itself that shows.
    const slots = useRef<{ current: HTMLDivElement | null }[]>([]);
    const slotFor = (i: number) => {
      slots.current[i] ??= { current: null };
      return slots.current[i];
    };
    // Every line the file lists, by position: each keeps its layer.
    const all = Children.toArray(children).filter(
      isValidElement,
    ) as ReactElement<TerminalSimulatorLineProps>[];
    const claims = useRef<{ current: Element | null }[]>([]);
    const claimFor = (j: number) => {
      claims.current[j] ??= { current: null };
      return claims.current[j];
    };
    const rest = { ...TerminalSimulatorDefaults, ...props };
    // What Studio is doing to each line that the file may not have yet.
    const [live, setLive] = useState<
      Record<number, TerminalSimulatorLineState>
    >({});
    const report = (j: number, state: TerminalSimulatorLineState) =>
      setLive((prev) =>
        JSON.stringify(prev[j]) === JSON.stringify(state)
          ? prev
          : { ...prev, [j]: state },
      );
    const merged = all.map((o, j) => {
      const st = live[j];
      return st
        ? {
            ...o.props,
            ...st.values,
            style: st.style,
            hidden: st.hidden,
            from: st.from,
            durationInFrames: st.durationInFrames,
          }
        : o.props;
    });
    // The ones the scene draws, in its order: the positions its `Item`s index.
    const kept = all.map((_, j) => j);
    const built = TerminalSimulatorFromItems(
      kept.map((j) => merged[j] as TerminalSimulatorLineValues),
    );
    const host =
      (frame: number): ItemHost =>
      (index, node) => {
        const j = kept[index];
        const m = j === undefined ? undefined : merged[j];
        if (j === undefined || !m) return node;
        // The layer's own visibility and timing, which its Sequence would apply
        // if it held the node.
        const start = m.from ?? 0;
        if (
          m.hidden ||
          frame < start ||
          frame >= start + (m.durationInFrames ?? Number.POSITIVE_INFINITY)
        )
          return null;
        const own = node as ReactElement<{
          ref?: Ref<Element>;
          style?: CSSProperties;
        }>;
        return cloneElement(own, {
          ref: claimFor(j),
          style: { ...own.props.style, ...m.style },
        });
      };
    // The scene measures its copy once, on mount, so a saved edit remounts it.
    // An edit still being typed does not: the scene would restart on every
    // keystroke. The layers are outside it and never remount with it.
    const key = JSON.stringify({
      ...rest,
      ...TerminalSimulatorFromItems(all.map((o) => o.props)),
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Terminal Simulator"}
        controls={controls}
        outlineRef={outlineRef}
        width={1280}
        height={720}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
          }}
        >
          {/* First, so each box's ref is set before the objects that move it
              run their layout effects on a fresh mount. */}
          {all.map((_, j) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: one box per position
              key={j}
              ref={slotFor(j)}
              style={{
                position: "absolute",
                display: "none",
                pointerEvents: "none",
                opacity: 0,
              }}
            />
          ))}
          <TerminalSimulatorFade>
            <TerminalSimulatorHosted host={host}>
              <TerminalSimulatorScene key={key} {...rest} {...built} />
            </TerminalSimulatorHosted>
          </TerminalSimulatorFade>
          {/* The layers, after the scene: its nodes are attached by the time
              they measure them. */}
          {all.map((o, j) =>
            cloneElement(o, {
              // biome-ignore lint/suspicious/noArrayIndexKey: one layer per position
              key: j,
              claim: claimFor(j),
              slot: slotFor(j),
              report: (state: TerminalSimulatorLineState) => report(j, state),
            }),
          )}
        </div>
      </Sequence>
    );
  },
);

const TerminalSimulatorStage = Interactive.withSchema({
  Component: TerminalSimulatorStageInner,
  componentName: "<TerminalSimulatorStage>",
  schema: TerminalSimulatorStageSchema,
  supportsEffects: false,
});

/**
 * Terminal Simulator: the scene, then each line as its own call site — select one on
 * the canvas or in the timeline and edit it here, or add, remove and reorder
 * them as JSX.
 */
export const TerminalSimulator = () => (
  <TerminalSimulatorStage
    intro="*work* one step at a *time.*"
    background="#ffffff"
    borderColor="#e4e4e7"
    fontSize={18}
    speed={1}
  >
    <TerminalSimulatorLine
      name="gh issue edit 42 --add-label bug"
      text="gh issue edit 42 --add-label bug"
      type="command"
    />
    <TerminalSimulatorLine
      name="→   label added"
